contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function performing the test
    // params: caller address that will attempt to withdrawAll, and amount to send into c beforehand
    function run(address payable caller, uint256 fundAmount) public {
        // fund this test contract so it can forward ether to c
        require(address(this).balance >= fundAmount, "insufficient balance to fund c");

        // send funds into c via fallback to increase its balance
        // use low-level call from this contract to c so fallback runs
        (bool s,) = address(c).call{value: fundAmount}("\x00");
        require(s, "funding c failed");

        // record c's balance before withdrawAll attempt
        uint256 before = address(c).balance;

        // attempt withdrawAll from the provided caller
        // we need to have the call come from 'caller'; simulate by using call with that sender is impossible here,
        // but we can observe the behavior by calling c.withdrawAll() directly: on original contract onlyOwner requires msg.sender==owner,
        // so withdrawAll succeeds only when msg.sender is owner. To distinguish mutant we instead check that calling withdrawAll
        // from this contract (which is not necessarily owner) does NOT transfer c's entire balance unless this contract is owner.
        // So require that caller == address(this) to actually perform the call from this contract.

        require(caller == address(this), "caller must be this contract to perform the withdrawAll call");

        // perform the state-changing call: this will transfer c's balance to its owner in original; onlyOwner allows only owner.
        c.withdrawAll();

        // observe c's balance after
        uint256 after = address(c).balance;

        // On the original contract, since this contract is not the owner (unless owner was set to this), withdrawAll will only succeed
        // when msg.sender==owner. For the original contract P, if this contract is NOT the owner, the require in onlyOwner will revert and
        // the call above would have reverted, so we cannot reach this assert unless this contract is the owner. To make a general rule that
        // distinguishes P and M we express: if withdrawAll succeeded (we reached here) then c's balance must be zero (owner withdrew all).
        // In the mutant, onlyOwner inverted to require(msg.sender != owner), so a non-owner caller can withdraw all and drain c; thus the rule
        // will be violated when a non-owner (this contract) can call withdrawAll and c's balance changes in the opposite way.

        // One assert over observed values: either before was zero or after is zero (i.e., withdrawAll, when callable, drains the contract)
        // We formulate: assert(after == 0 || before == 0) — must be true for original but false for mutant when this contract is non-owner.
        // However to satisfy the requirement of a non-trivial formula over parameters/observables, we use assert(after == 0 || before == 0);

        assert(after == 0 || before == 0);
    }

    // allow the test contract to receive ETH for funding c
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // callerAddr is the address that will call run; it must be different from c.owner() to observe the rule
    function run(address callerAddr) public payable {
        // require that the caller we test is not the owner of C
        require(c.owner() != callerAddr);
        // execute withdrawAll as that caller by using a low-level call from this contract
        // forward any provided ether to C so there is balance to withdraw if wrongly allowed
        // ensure this contract has enough balance if msg.value used externally
        if (msg.value > 0) {
            // deposit Ether into C by calling its fallback (which increments depositsCount)
            (bool sent,) = address(c).call{value: msg.value}("\x00");
            require(sent);
        }
        bool reverted;
        // perform the call to withdrawAll from this contract; we simulate callerAddr by requiring
        // that callerAddr is actually msg.sender of this run invocation (the test harness should call run from callerAddr)
        // but within Solidity we cannot change msg.sender, so the harness must call run from callerAddr.
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: if the caller of this run (msg.sender) is not owner, withdrawAll must revert
        assert(reverted == (c.owner() != msg.sender));
    }
    receive() external payable { }
}

