import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller (as owner) will call sendMoney, target is an adversarial helper that always accepts funds
    function testFuzz_property(address target, uint256 value) public {
        // keep target non-zero
        vm.assume(target != address(0));
        // bound the value to something reasonable so vm.deal won't overflow; keep wide
        value = bound(value, 0, 1 ether);

        // Ensure the contract has some balance to send
        vm.deal(address(this), 1 ether);

        // The owner is the test contract (msg.sender at construction), so we act as that owner
        // Deploy a simple receiver that accepts funds to make external call behave like a normal payable callee
        Receiver r = Receiver(payable(target));
        // If the fuzzed address does not contain code, deploy our Receiver at that address isn't possible.
        // To satisfy the adversarial counterparty requirement (external callee must be a contract),
        // if the provided target has no code, deploy our own Receiver and use its address instead.
        if (isContract(target) == false) {
            r = new Receiver();
            target = address(r);
        }

        // Fund c so sendMoney can transfer value
        // owner (this) will send ETH to c
        // send ETH to c
        (bool s,) = address(c).call{value: value}("");
        require(s);

        // Record balance before the owner calls sendMoney
        uint256 before = address(c).balance;

        // Owner (this test contract) calls sendMoney on c
        // As constructed, this contract is the owner of c, so this should succeed on reference
        // and (in the reference) allow the owner to later withdrawAll; mutant prevents owner from calling sendMoney
        // Call sendMoney and catch revert to observe success/failure
        bool ok;
        try c.sendMoney{value: 0}(target, value, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // After performing sendMoney (which may have transferred funds out), the owner should always be able to call withdrawAll
        // In the reference contract, owner can call withdrawAll regardless of prior sendMoney outcome; to observe the effect
        // we attempt withdrawAll and observe final contract balance.
        // Call withdrawAll and ignore revert (it should not revert in reference)
        bool withdrawOk;
        try c.withdrawAll() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // The universal property we assert: on the reference contract, withdrawAll should succeed (withdrawOk == true)
        // for all admissible inputs. The mutant inverts onlyOwner and will make withdrawAll revert when the owner
        // was prevented from calling sendMoney or similar; thus withdrawOk distinguishes behavior.
        assertTrue(withdrawOk);

        // Additionally ensure we actually observed a meaningful scenario by checking the contract balance after withdrawAll is zero
        // (This is not strictly necessary for the single required assertTrue, but is safe since reference should allow owner to withdraw all.)
        assertTrue(address(c).balance == 0);
    }

    // helper to detect code at an address
    function isContract(address addr) internal view returns (bool) {
        uint256 size;
        assembly { size := extcodesize(addr) }
        return size > 0;
    }
}

