import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: actor (address) and value (uint256)
    // property: when the owner (the deployer) calls sendMoney(...){value: v}, the call is permitted by the reference
    // and after the call the owner can withdraw the contract's balance via withdrawAll; the mutant forbids the owner
    // and thus can change outcomes for some inputs.
    function testFuzz_property(address actor, uint256 value) public {
        // ensure actor is the owner (deployer) to exercise the permitted path on the reference
        // the owner is address(this) at deployment of C in setUp() because setUp created c from this test contract
        address owner = address(this);
        vm.assume(actor == owner);

        // bound the value to a reasonable range so vm.deal doesn't overflow and c has funds
        uint256 v = bound(value, 0, 1 ether);

        // fund the test contract (the owner) so it can send value into c and also send value via sendMoney
        vm.deal(owner, 10 ether);

        // deposit some initial ether into c by calling its payable fallback via a plain transfer
        // send 1 ether to c so withdrawAll has something to withdraw after sendMoney
        (bool sentToC,) = address(c).call{value: 1 ether}("unused");
        require(sentToC);

        // Now owner calls sendMoney on c to forward up to v to a harmless target (an EOA address).
        // Use address(0xBEEF) as a target EOA (no code), low-level call will succeed if allowed.
        vm.prank(owner);
        bool ok;
        try c.sendMoney(address(0xBEEF), v, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // After the above, regardless of success of the sendMoney call, the owner must be able to call withdrawAll
        // on the reference contract; withdrawAll on the reference simply forwards the current balance to owner.
        // We assert that withdrawAll does NOT revert (i.e., succeeds). We detect revert by try/catch and assertTrue on success flag.
        bool withdrawSucceeds;
        try c.withdrawAll() {
            withdrawSucceeds = true;
        } catch {
            withdrawSucceeds = false;
        }

        // single assertion: on the reference contract, when the deployer (owner) is the caller above,
        // withdrawAll must succeed for all admissible inputs; the mutant that inverts onlyOwner will break this for some inputs.
        assertTrue(withdrawSucceeds);
    }
}

