pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed parameter: adversarial owner initial balance (amount to fund contract) and a boolean to choose an adversarial owner that reverts on receive
    function testFuzz_property(uint256 fundAmount, bool ownerReverts) public {
        // keep fundAmount in a reasonable range
        fundAmount = bound(fundAmount, 0, 10 ether);

        // deploy an adversarial owner contract if needed
        address ownerAddr;
        Reverter rev;
        NonReverting nr;
        if (ownerReverts) {
            rev = new Reverter();
            ownerAddr = address(rev);
        } else {
            nr = new NonReverting();
            ownerAddr = address(nr);
        }

        // Fund the test contract c with ETH so withdrawAll has something to send
        vm.deal(address(this), fundAmount);
        // send fundAmount into c via fallback by calling with value
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent);

        // Now change owner of c to our adversarial owner by using low-level storage write is not allowed.
        // But the contract sets owner = deployer in constructor. We deployed c as this test contract, so we need to have this test contract be the owner.
        // To simulate the owner receiving funds, we will call withdrawAll while using the adversarial address as msg.sender via vm.prank.
        // vm.prank with an address that is a contract will make msg.sender that contract for the call, and the contract's receive/fallback will be invoked when c.transfer is executed.

        // ensure the adversarial address has some balance so transfer can credit it if needed
        vm.deal(ownerAddr, 1 wei);

        bool ok;
        // call withdrawAll as if msg.sender is the adversarial owner
        vm.prank(ownerAddr);
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: for the reference contract, withdrawAll always routes through withdraw(uint) which transfers to msg.sender via payable(msg.sender).transfer(_value) inside withdraw(); that means withdrawAll's observable success/failure when msg.sender's fallback reverts MUST match calling withdraw(address(this).balance) (i.e., the call we just made). In other words, if msg.sender's fallback reverts on receiving funds, withdrawAll MUST revert (ok == false). The mutated version that does a direct payable(msg.sender).transfer(address(this).balance) from withdrawAll may behave differently for some inputs; thus we assert the reference behavior: withdrawAll reverts when the recipient reverts on receive. We encode that as: if ownerReverts == true then the call should have failed (ok == false); if ownerReverts == false then the call should have succeeded (ok == true).
        assertTrue(ownerReverts ? ok == false : ok == true);
    }
}

// helper that reverts on any receive/call
contract Reverter {
    receive() external payable { revert("no receive"); }
    fallback() external payable { revert("no fallback"); }
}

// helper that accepts funds
contract NonReverting {
    receive() external payable {}
    fallback() external payable {}
