pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the deposit amount and a boolean deciding whether the adversarial owner reverts on receive
    function testFuzz_property(uint256 depositAmount, bool ownerReverts) public {
        // keep depositAmount in a reasonable range but allow zero as well
        depositAmount = bound(depositAmount, 0, 1 ether);

        // deploy an adversarial owner that optionally reverts on receive
        AdversarialOwner adv = new AdversarialOwner(ownerReverts);

        // fund the adversarial owner so it can become msg.sender for withdrawAll without needing external funds
        vm.deal(address(adv), 0);

        // make adv the owner of c by constructing c with msg.sender as deployer already set in setUp;
        // we need c.owner to be adv. To achieve this, we must deploy a fresh C with adv as deployer.
        // So redeploy c from adv's context.
        c = deployCAs(address(adv));

        // fund the contract c so withdrawAll has balance to transfer
        vm.deal(address(c), depositAmount);

        // call withdrawAll as the owner (adv). Use vm.prank to make msg.sender == adv
        bool ok;
        vm.prank(address(adv));
        try c.withdrawAll{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (single assertion): For the reference C, withdrawAll should revert iff sending the same amount
        // via withdraw(uint) to msg.sender would revert. We can observe that by calling withdraw(uint) in a try/catch
        // from adv (but withdraw is onlyOwner so must be called by adv). We compare results: both calls should have same ok.
        bool ok_withdraw;
        vm.prank(address(adv));
        try c.withdraw(address(c).balance) {
            ok_withdraw = true;
        } catch {
            ok_withdraw = false;
        }

        // The reference C satisfies ok == ok_withdraw for all inputs; the mutant that bypasses withdraw(uint)
        // can make these differ for some inputs (ownerReverts == true). Assert this equality.
        assertTrue(ok == ok_withdraw);
    }

    // helper to deploy C with an arbitrary deployer (simulate adv deploying C so owner==adv)
    function deployCAs(address deployer) internal returns (C) {
        // create bytecode for C deployment by calling from deployer
        vm.prank(deployer);
        C local = new C();
        return local;
    }
}

// adversarial owner that optionally reverts on receive/fallback
contract AdversarialOwner {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) revert("no receive");
    }
    fallback() external payable {
        if (shouldRevert) revert("no fallback");
    }
}

